package integration_test
import("context";"testing";"time";"github.com/vance1852/foodsafe-traceability/internal/permit")
func TestShipmentReleaseRollsBackWhenAuditFails(t *testing.T){f:=newFixture(t);g:=f.createSourceGraph(t);now:=time.Now().UTC();p,err:=f.permits.Create(context.Background(),f.supervisor,permit.CreateCommand{FacilityID:g.source.ID,HolderName:"Plant",Reference:"PRIVATE-REL",ValidFrom:now.Add(-time.Hour),ValidUntil:now.Add(time.Hour),DailyVolumeLimitLiters:1000,RequestID:"private-release-permit"});if err!=nil{t.Fatal(err)};if err=f.permits.Activate(context.Background(),f.supervisor,p.ID,"private-release-activate");err!=nil{t.Fatal(err)};if _,err=f.store.DB().Exec(`CREATE TRIGGER fail_shipment_release_audit BEFORE INSERT ON audit_events WHEN NEW.action = 'shipment release.report' BEGIN SELECT RAISE(ABORT, 'audit sink unavailable'); END`);err!=nil{t.Fatal(err)};_,_,err=f.permits.ReportShipmentRelease(context.Background(),f.supervisor,permit.ReportShipmentReleaseCommand{PermitID:p.ID,IdempotencyKey:"private-release-key",VolumeLiters:100,OccurredAt:now,RequestID:"private-release-failing"});if err==nil{t.Fatal("release unexpectedly succeeded")};var count int;if err=f.store.DB().QueryRow(`SELECT COUNT(*) FROM shipment_release_events WHERE permit_id=?`,p.ID).Scan(&count);err!=nil{t.Fatal(err)};if count!=0{t.Fatalf("failed release persisted %d events",count)};if _,err=f.store.DB().Exec(`DROP TRIGGER fail_shipment_release_audit`);err!=nil{t.Fatal(err)};_,created,err:=f.permits.ReportShipmentRelease(context.Background(),f.supervisor,permit.ReportShipmentReleaseCommand{PermitID:p.ID,IdempotencyKey:"private-release-key",VolumeLiters:100,OccurredAt:now,RequestID:"private-release-retry"});if err!=nil||!created{t.Fatalf("retry created=%v err=%v",created,err)}}
